import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import{capsule}from'../../core/geometry.js';
export function grove(host){const frame=new THREE.Group();frame.name='Gateway H2 physical blue open-top HY2.0-4P socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const plastic=materials.plastic(spec.grove.color,{roughness:.65}),metal=materials.metal(0xb6b49a,{roughness:.42}),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'Gateway H2 Grove '+n);
 for(const sign of[-1,1]){box([.65,5.2,6.3],[sign*4.675,0,-3.15],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}
 box([8.7,.65,6.3],[0,-2.275,-3.15],'floor');box([8.7,4.55,.65],[0,.325,-5.975],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-5.8],`solder tail ${i+1}`,metal);}
 const port=host.add(new Port({id:'grove',label:'PORT.C · UART RX/TX',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'UART_RX',color:'yellow'},{n:4,name:'UART_TX',color:'white'}],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.2],order:col=>4-col},meta:{role:'visual-connector',face:'bottom',scope:'Physical four contacts,documented labels,attachment and cable pose only;no UART,USB,boot mode,radio,network,Thread,Matter,Zigbee,power,electrical or firmware behavior'}}));return{frame,contacts,port};}
export function usb(host,{interactive=false}={}){const frame=new THREE.Group();frame.name='Gateway H2 physical internal service USB-C socket';frame.position.fromArray(spec.usb.position);frame.quaternion.copy(FACE.right);host.body.add(frame);const metal=materials.metal(0xb8bcb6,{roughness:.43}),inside=materials.plastic(0x202720,{roughness:.82}),gold=materials.metal(0xc9b574,{roughness:.43}),shape=capsule(8.8,3.2);shape.holes.push(capsule(8,2.4,{path:new THREE.Path(),clockwise:true}));const shell=mesh(frame,new THREE.ExtrudeGeometry(shape,{depth:6.3,bevelEnabled:false,curveSegments:48}),metal,[0,0,-6.3],'Gateway H2 USB-C actual annular rounded metal shell and open mouth'),rear=mesh(frame,new THREE.BoxGeometry(7.85,2.25,.5),inside,[0,0,-6.05],'Gateway H2 USB-C recessed dielectric rear carrier'),tongue=mesh(frame,new THREE.BoxGeometry(6.25,.55,4.9),inside,[0,0,-3.05],'Gateway H2 USB-C retained real insulating tongue');const contacts=[];for(const sign of[-1,1])for(let i=0;i<12;i++)contacts.push(mesh(frame,new THREE.BoxGeometry(.22,.07,3.7),gold,[(i-5.5)*.5,sign*.31,-2.9],'Gateway H2 USB-C physical contact finger envelope,exact connector BOM unconfirmed'));const tabs=[];for(const side of[-1,1])tabs.push(mesh(frame,new THREE.BoxGeometry(.6,.65,1.7),metal,[side*3.75,-1.55,-5.4],'Gateway H2 USB-C PCB metal retention tab'));const port=interactive?host.add(new Port({id:'usb',label:'USB-C · bare-PCB service connector',connector:'usb-c',position:spec.usb.position,quaternion:portQuaternion('right'),hitSize:[8.8,1,3.2],pins:['VBUS','GND','D+','D-','CC1','CC2'].map(name=>({name})),meta:{role:'visual-connector',face:'right',serviceOnly:true,source:'Own U195_04 bare-board photograph and U195_download_mode1.gif;closed official casing has no side USB opening',scope:'Physical socket and attachment only in explicit shell:false configuration;no USB enumeration,serial data,power,firmware flashing,boot state,protocol or electrical behavior'}})):null;return{frame,shell,rear,tongue,contacts,tabs,port};}
